#include <bits/stdc++.h>
using namespace std;
#define MOD_CONST 1000000007
typedef unsigned long long ull_type;

struct MatrixType {
    ull_type matrix[35][35];
    int dimension;
    friend MatrixType operator*(const MatrixType &A, const MatrixType &B) {
        MatrixType C;
        C.dimension = A.dimension;
        for (int i = 0; i < A.dimension; ++i) {
            for (int j = 0; j < A.dimension; ++j) {
                C.matrix[i][j] = 0;
                for (int k = 0; k < A.dimension; ++k) {
                    C.matrix[i][j] += A.matrix[i][k] * B.matrix[k][j];
                }
                C.matrix[i][j] %= MOD_CONST;
            }
        }
        return C;
    }
};

int main() {
    ull_type n_input, m_input;
    cin >> n_input >> m_input;
    MatrixType baseMatrix, identityMatrix;
    baseMatrix.dimension = m_input + 1;
    for (int i = 0; i <= m_input; ++i) {
        baseMatrix.matrix[i][i] = 1;
        baseMatrix.matrix[0][i] = 1;
    }
    identityMatrix.dimension = m_input + 1;
    for (int i = 0; i <= m_input; ++i) {
        identityMatrix.matrix[i][i] = 1;
    }

    ull_type yVal = 1, yPow = 1, levelIdx = 0, total = 0;
    while (yPow * m_input <= n_input) {
        yPow *= m_input;
        ++levelIdx;
    }

    vector<vector<MatrixType>> biMatrices(levelIdx + 1, vector<MatrixType>(m_input + 1));
    for (int t = 0; t <= levelIdx; ++t) {
        if (t > 0) {
            biMatrices[t][0] = biMatrices[t - 1][0];
            for (int i = 1; i <= m_input; ++i) {
                biMatrices[t][0] = biMatrices[t][0] * biMatrices[t - 1][i];
            }
        }
        for (int i = 1; i <= m_input; ++i) {
            biMatrices[t][i] = biMatrices[t][i - 1];
            for (int j = m_input - 2; j >= 0; --j) {
                for (int k = 0; k <= m_input; ++k) {
                    swap(biMatrices[t][i].matrix[j][k], biMatrices[t][i].matrix[j + 1][k]);
                }
            }
            for (int j = m_input - 2; j >= 0; --j) {
                for (int k = 0; k <= m_input; ++k) {
                    swap(biMatrices[t][i].matrix[k][j], biMatrices[t][i].matrix[k][j + 1]);
                }
            }
        }
    }

    MatrixType current = identityMatrix;
    while (total < n_input) {
        if (total + yPow <= n_input) {
            total += yPow;
            current = current * biMatrices[levelIdx][0];
            yVal = (yVal + 1) % m_input;
        } else {
            yPow /= m_input;
            --levelIdx;
        }
    }

    ull_type answerSum = 0;
    for (int i = 0; i <= m_input; ++i) {
        answerSum = (answerSum + current.matrix[i][m_input]) % MOD_CONST;
    }
    cout << answerSum << "\n";
}
